import {mkdir, writeFile} from 'node:fs/promises'
import {createCapillaryUiRuntime} from '@capillaryjs/capillary-ui'
import {TraceInspector} from '../src/views/TraceInspector.tsx'

const runtime = createCapillaryUiRuntime()
runtime.registerStyles(TraceInspector)
await mkdir(new URL('../styles', import.meta.url), {recursive: true})
await writeFile(new URL('../styles/structural.css', import.meta.url),
    '/* Generated by scripts/build-structural-css.mjs. */\n' + runtime.styleRegistry.generateCSS() + '\n')
